use rdkafka::{ClientConfig,Message,Offset,TopicPartitionList,client::ClientContext,consumer::{BaseConsumer,Consumer,ConsumerContext},statistics::Statistics};
use std::{sync::{Arc,atomic::{AtomicUsize,Ordering}},time::{Duration,Instant}};
#[derive(Clone)]struct C(Arc<AtomicUsize>);impl ClientContext for C{fn stats(&self,_:Statistics){self.0.fetch_add(1,Ordering::SeqCst);}}impl ConsumerContext for C{}
fn main()->Result<(),Box<dyn std::error::Error>>{let args:Vec<String>=std::env::args().collect();let c:serde_json::Value=serde_json::from_slice(&std::fs::read(&args[1])?)?;let topic=c["source"]["topic"].as_str().unwrap();let count=Arc::new(AtomicUsize::new(0));let con:BaseConsumer<C>=ClientConfig::new().set("bootstrap.servers",c["mode"]["config"]["brokers"].as_str().unwrap()).set("group.id",format!("seek-review-{}",std::process::id())).set("enable.auto.commit","false").set("enable.auto.offset.store","false").set("isolation.level","read_committed").set("enable.partition.eof","true").set("statistics.interval.ms","100").create_with_context(C(count.clone()))?;let mut tpl=TopicPartitionList::new();tpl.add_partition_offset(topic,0,Offset::End)?;con.assign(&tpl)?;let target=con.fetch_watermarks(topic,0,Duration::from_secs(10))?.1;assert_eq!(target,300);let mut cases=vec![];
for cycle in 0..10{con.seek(topic,0,Offset::Offset(target),Duration::from_secs(10))?;std::thread::sleep(Duration::from_millis(500));let old_stats=count.load(Ordering::SeqCst);con.seek(topic,0,Offset::Offset(0),Duration::from_secs(10))?;let mut seen=vec![];let start=Instant::now();loop{assert!(start.elapsed()<Duration::from_secs(10));match con.poll(Duration::ZERO){Some(Ok(m))=>seen.push(m.offset()),Some(Err(rdkafka::error::KafkaError::PartitionEOF(0)))=>break,Some(Err(e))=>return Err(e.into()),None=>std::thread::sleep(Duration::from_millis(1))}}assert_eq!(seen,(0..target).collect::<Vec<_>>());cases.push(serde_json::json!({"cycle":cycle,"records_before_current_EOF":seen.len(),"statistics_callbacks_during_post_seek_poll":count.load(Ordering::SeqCst)-old_stats}));}println!("{}",serde_json::json!({"passed":true,"scope":"pinned librdkafka actual queued statistics/EOF across repeated seek from end to beginning; candidate clears its own EOF/statistics maps","target":target,"cycles":cases}));Ok(())}
